-- Commands sent to the edge adapter (docs/contracts/command-v1.md). The id is the
-- commandId of the contract, generated by the core, so no sequence is needed.
-- type and status hold the names of the Java enums CommandType and CommandStatus.
CREATE TABLE command (
    id           uuid         PRIMARY KEY,
    drone_id     integer      NOT NULL,
    type         varchar(32)  NOT NULL,
    params       jsonb        NOT NULL,
    status       varchar(16)  NOT NULL,
    detail       text,
    issued_at    timestamptz  NOT NULL,
    completed_at timestamptz,
    issued_by    text
);

CREATE INDEX idx_command_drone_issued ON command (drone_id, issued_at);
